  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  backdrop-filter: blur(6px);
  transition: transform var(--transition), background var(--transition);
}
.hero-card:hover { transform: translateY(-4px); background: rgba(255,255,255,.13); }
.hero-card:first-child { grid-column: span 2; }
.hero-card-img {
  width: 100%;
  aspect-ratio: 16/9;
  border-radius: var(--radius-md);
  object-fit: cover;
  background: rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  margin-bottom: .9rem;
}
.hero-card-label { font-size: .78rem; font-weight: 600; color: rgba(255,255,255,.55); text-transform: uppercase; letter-spacing: .06em; }
.hero-card-name { font-size: 1rem; font-weight: 700; margin: .2rem 0 .4rem; }
.hero-card-price { font-size: .95rem; color: var(--clr-accent); font-weight: 700; }

/* ── Section commons ── */
section { padding: 4.5rem 0; }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}
.section-eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: .5rem;
}
.section-title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.025em;
  line-height: 1.2;
}
.section-desc { color: var(--clr-muted); font-size: .95rem; margin-top: .4rem; }
.view-all {
  white-space: nowrap;
  font-size: .875rem;
  font-weight: 600;
  color: var(--clr-accent);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: .3rem;
  padding: .4rem .8rem;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.view-all:hover, .view-all:focus-visible {
  background: var(--clr-tag-bg);
  text-decoration: underline;
}
.view-all:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }

/* ── Category bar ── */
.category-bar { padding: 1.5rem 0 0; }
.category-list {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: .5rem;
}
.category-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .55rem 1.2rem;
  border: 1.5px solid var(--clr-border);
  border-radius: 50px;
  background: var(--clr-surface);
  font-family: var(--font);
  font-size: .875rem;
  font-weight: 500;
  color: var(--clr-text);
  cursor: pointer;
  white-space: nowrap;
  transition: border-color var(--transition), background var(--transition), color var(--transition), transform var(--transition);
  text-decoration: none;
}
.category-chip:hover, .category-chip:focus-visible {
  border-color: var(--clr-accent);
  color: var(--clr-accent);
  transform: translateY(-2px);
}
.category-chip[aria-pressed="true"], .category-chip.active {
  background: var(--clr-accent);
  border-color: var(--clr-accent);
  color: #fff;
}
.category-chip:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }
.category-chip-icon { font-size: 1.1rem; }

/* ── Products grid ── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}
.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  border: 1px solid var(--clr-border);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }

.product-img-wrap {
  position: relative;
  aspect-ratio: 4/3;
  background: var(--clr-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  overflow: hidden;
}
.product-badges {
  position: absolute;
  top: .75rem;
  left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
}
.badge {
  display: inline-block;
  padding: .2rem .6rem;
  border-radius: 50px;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge-new { background: var(--clr-brand); color: #fff; }
.badge-sale { background: var(--clr-accent); color: #fff; }
.badge-hot { background: #ff8c00; color: #fff; }
.badge-limited { background: #6c3fc5; color: #fff; }

.product-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
  background: var(--clr-surface);
  border: none;
  border-radius: 50%;
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--clr-muted);
  font-size: 1rem;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  transition: color var(--transition), transform var(--transition);
}
.product-wishlist:hover, .product-wishlist:focus-visible {
  color: var(--clr-accent);
  transform: scale(1.1);
}
.product-wishlist[aria-pressed="true"] { color: var(--clr-accent); }
.product-wishlist:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }

.product-info { padding: 1rem 1.1rem 1.2rem; flex: 1; display: flex; flex-direction: column; }
.product-category { font-size: .72rem; font-weight: 600; color: var(--clr-muted); text-transform: uppercase; letter-spacing: .06em; }
.product-name {
  font-size: .97rem;
  font-weight: 700;
  margin: .3rem 0 .5rem;
  line-height: 1.35;
}
.product-name a {
  color: inherit;
  text-decoration: none;
}
.product-name a:hover, .product-name a:focus-visible { color: var(--clr-accent); text-decoration: underline; }
.product-name a:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }
.product-rating {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .8rem;
  color: var(--clr-muted);
  margin-bottom: .75rem;
}
.stars { color: #f59e0b; letter-spacing: 1px; }
.product-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
}
.product-price { display: flex; align-items: baseline; gap: .4rem; flex-wrap: wrap; }
.price-current { font-size: 1.1rem; font-weight: 800; color: var(--clr-text); }
.price-original { font-size: .85rem; color: var(--clr-muted); text-decoration: line-through; }
.price-save { font-size: .72rem; font-weight: 700; color: var(--clr-accent); }

.add-to-cart {
  background: var(--clr-brand);
  color: #fff;
  border: none;
  border-radius: 50px;
  padding: .5rem 1rem;
  font-family: var(--font);
  font-size: .82rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background var(--transition), transform var(--transition);
}
.add-to-cart:hover, .add-to-cart:focus-visible {
  background: var(--clr-accent);
  transform: scale(1.03);
}
.add-to-cart:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 3px; }
.add-to-cart.added { background: #16a34a; }

/* ── Deals ── */
.deals-section { background: var(--clr-brand); color: #fff; }
.deals-section .section-eyebrow { color: var(--clr-accent); }
.deals-section .section-title { color: #fff; }
.deals-section .section-desc { color: rgba(255,255,255,.6); }
.deals-section .view-all { color: #ffb3bf; }
.deals-section .view-all:hover { background: rgba(255,255,255,.08); }

.deals-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 1.25rem;
}
.deal-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), background var(--transition);
  display: flex;
  flex-direction: column;
}
.deal-card:hover { transform: translateY(-4px); background: rgba(255,255,255,.11); }
.deal-card.featured { grid-row: span 2; }
.deal-card-media {
  aspect-ratio: 4/3;
  background: rgba(255,255,255,.05);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  position: relative;
}
.deal-card.featured .deal-card-media { aspect-ratio: 1/1; font-size: 6rem; }
.deal-discount {
  position: absolute;
  bottom: .75rem;
  left: .75rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .85rem;
  font-weight: 800;
  padding: .3rem .8rem;
  border-radius: 50px;
}
.deal-card-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.deal-label { font-size: .72rem; font-weight: 700; color: rgba(255,255,255,.5); text-transform: uppercase; letter-spacing: .08em; margin-bottom: .35rem; }
.deal-name { font-size: 1rem; font-weight: 700; margin-bottom: .5rem; line-height: 1.3; }
.deal-card.featured .deal-name { font-size: 1.3rem; }
.deal-price-row { display: flex; align-items: baseline; gap: .6rem; margin-bottom: .9rem; }
.deal-price-new { font-size: 1.2rem; font-weight: 800; }
.deal-card.featured .deal-price-new { font-size: 1.6rem; }
.deal-price-old { font-size: .88rem; color: rgba(255,255,255,.45); text-decoration: line-through; }

.countdown { display: flex; gap: .5rem; margin-bottom: 1.1rem; }
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,.1);
  border-radius: var(--radius-sm);
  padding: .4rem .6rem;
  min-width: 44px;
}
.countdown-num { font-size: 1.1rem; font-weight: 800; line-height: 1; }
.countdown-label { font-size: .6rem; color: rgba(255,255,255,.5); text-transform: uppercase; margin-top: .2rem; }
.deal-progress { margin-bottom: 1rem; }
.deal-progress-bar {
  height: 5px;
  background: rgba(255,255,255,.15);
  border-radius: 50px;
  overflow: hidden;
  margin-top: .4rem;
}
.deal-progress-fill {
  height: 100%;
  background: var(--clr-accent);
  border-radius: 50px;
  transition: width 1s ease;
}
.deal-progress-text { font-size: .72rem; color: rgba(255,255,255,.55); }
.deal-btn {
  margin-top: auto;
  background: var(--clr-accent);
  color: #fff;
  border: none;
  border-radius: 50px;
  padding: .7rem 1.4rem;
  font-family: var(--font);
  font-size: .88rem;
  font-weight: 700;
  cursor: pointer;
  text-align: center;
  transition: background var(--transition), transform var(--transition);
  text-decoration: none;
  display: block;
}
.deal-btn:hover, .deal-btn:focus-visible {
  background: var(--clr-accent-dark);
  transform: translateY(-2px);
}
.deal-btn:focus-visible { outline: 3px solid #fff; outline-offset: 3px; }

/* ── Trust strip ── */
.trust-strip { background: var(--clr-surface); border-top: 1px solid var(--clr-border); border-bottom: 1px solid var(--clr-border); padding: 2rem 0; }
.trust-list {
  display: flex;
  justify-content: space-around;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  flex: 1;
  min-width: 160px;
  max-width: 220px;
}
.trust-icon { font-size: 1.8rem; flex-shrink: 0; }
.trust-title { font-size: .9rem; font-weight: 700; }
.trust-sub { font-size: .78rem; color: var(--clr-muted); }

/* ── Editorial ── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  background: var(--clr-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  border: 1px solid var(--clr-border);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }
.editorial-card.featured { grid-column: span 2; flex-direction: row; }
.editorial-img {
  aspect-ratio: 16/9;
  background: var(--clr-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  flex-shrink: 0;
}
.editorial-card.featured .editorial-img {
  aspect-ratio: auto;
  flex: 0 0 44%;
  font-size: 4rem;
}
.editorial-body { padding: 1.4rem; flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  display: inline-block;
  background: var(--clr-tag-bg);
  color: var(--clr-tag-text);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  padding: .25rem .7rem;
  border-radius: 50px;
  margin-bottom: .8rem;
}
.editorial-title {
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: .6rem;
}
.editorial-card.featured .editorial-title { font-size: 1.3rem; }
.editorial-title a { color: inherit; text-decoration: none; }
.editorial-title a:hover, .editorial-title a:focus-visible { color: var(--clr-accent); text-decoration: underline; }
.editorial-title a:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }
.editorial-excerpt { font-size: .875rem; color: var(--clr-muted); line-height: 1.6; margin-bottom: 1rem; flex: 1; }
.editorial-meta { display: flex; align-items: center; gap: .75rem; font-size: .78rem; color: var(--clr-muted); }
.editorial-meta-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--clr-accent);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .75rem;
  font-weight: 700;
  flex-shrink: 0;
}
.editorial-read-more {
  font-size: .82rem;
  font-weight: 600;
  color: var(--clr-accent);
  text-decoration: none;
  margin-top: .8rem;
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  align-self: flex-start;
}
.editorial-read-more:hover, .editorial-read-more:focus-visible { text-decoration: underline; }
.editorial-read-more:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }

/* ── Newsletter ── */
.newsletter-section {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%);
  color: #fff;
  padding: 4rem 0;
}
.newsletter-inner {
  display: flex;
  align-items: center;
  gap: 3rem;
  flex-wrap: wrap;
}
.newsletter-copy { flex: 1; min-width: 260px; }
.newsletter-eyebrow {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: .6rem;
}
.newsletter-title {
  font-size: clamp(1.4rem, 3vw, 1.9rem);
  font-weight: 800;
  letter-spacing: -.025em;
  margin-bottom: .6rem;
}
.newsletter-desc { color: rgba(255,255,255,.6); font-size: .95rem; }
.newsletter-form { flex: 1; min-width: 280px; max-width: 480px; }
.newsletter-input-row {
  display: flex;
  gap: .5rem;
  margin-bottom: .8rem;
}
.newsletter-input-row input {
  flex: 1;
  padding: .75rem 1.2rem;
  border: 1.5px solid rgba(255,255,255,.2);
  border-radius: 50px;
  background: rgba(255,255,255,.08);
  color: #fff;
  font-family: var(--font);
  font-size: .9rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.newsletter-input-row input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-input-row input:focus {
  outline: none;
  border-color: var(--clr-accent);
  box-shadow: 0 0 0 3px rgba(233,69,96,.2);
}
.newsletter-note { font-size: .75rem; color: rgba(255,255,255,.4); }
.newsletter-note a { color: rgba(255,255,255,.6); }

/* ── Footer ── */
.site-footer {
  background: var(--clr-brand);
  color: rgba(255,255,255,.7);
  padding: 3.5rem 0 2rem;
  font-size: .88rem;
}
.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.footer-brand .nav-logo { display: inline-block; margin-bottom: .85rem; color: #fff; }
.footer-brand p { line-height: 1.7; max-width: 280px; margin-bottom: 1.25rem; }
.footer-socials { display: flex; gap: .5rem; }
.social-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.15);
  background: transparent;
  color: rgba(255,255,255,.6);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .85rem;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
  text-decoration: none;
}
.social-btn:hover, .social-btn:focus-visible {
  background: var(--clr-accent);
  color: #fff;
  border-color: var(--clr-accent);
}
.social-btn:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; }

.footer-col h3 { font-size: .85rem; font-weight: 700; color: #fff; letter-spacing: .05em; text-transform: uppercase; margin-bottom: 1rem; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: .55rem; }
.footer-col a { color: rgba(255,255,255,.6); text-decoration: none; transition: color var(--transition); }
.footer-col a:hover, .footer-col a:focus-visible { color: #fff; }
.footer-col a:focus-visible { outline: 3px solid var(--clr-accent); outline-offset: 2px; border-radius: 2px; }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-legal { display: flex; gap: 1.25rem; flex-wrap: wrap; }
.footer-legal a { color: rgba(255,255,255,.45); text-decoration: none; font-size: .8rem; transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.8); }
.payment-methods { display: flex; gap: .5rem; align-items: center; }
.payment-badge {
  background: rgba(255,255,255,.12);
  color: rgba(255,255,255,.7);
  font-size: .7rem;
  font-weight: 700;
  padding: .25rem .55rem;
  border-radius: 4px;
  letter-spacing: .04em;
}

/* ── Toast ── */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: .6rem;
  pointer-events: none;
}
.toast {
  background: var(--clr-brand);
  color: #fff;
  padding: .8rem 1.2rem;
  border-radius: var(--radius-md);
  box-shadow: 0 8px 32px rgba(0,0,0,.2);
  font-size: .875rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: .6rem;
  animation: slideIn .28s ease;
  pointer-events: auto;
  max-width: 300px;
}
.toast.success .toast-icon { color: #4ade80; }
.toast.error .toast-icon { color: var(--clr-accent); }
@keyframes slideIn {
  from { opacity: 0; transform: translateX(40px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes fadeOut {
  from { opacity: 1; }
  to { opacity: 0; transform: translateX(40px); }
}
.toast.hiding { animation: fadeOut .28s ease forwards; }

/* ── Responsive ── */
@media (max-width: 960px) {
  .hero-inner { grid-template-columns: 1fr; padding: 3rem 0; }
  .hero-visual { display: none; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card.featured { grid-column: span 2; grid-row: span 1; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.featured { grid-column: span 2; flex-direction: column; }
  .editorial-card.featured .editorial-img { flex: none; aspect-ratio: 16/9; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .footer-brand { grid-column: span 2; }
}

@media (max-width: 680px) {
  .nav-links { display: none; }
  .nav-search { display: none; }
  .nav-menu-btn { display: flex; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.featured { grid-column: span 1; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.featured { grid-column: span 1; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
  .products-grid { grid-template-columns: 1fr 1fr; }
  .hero-stats { gap: 1.25rem; }
  .newsletter-input-row { flex-direction: column; }
  .newsletter-input-row input { border-radius: var(--radius-md); }
  .newsletter-input-row .btn { border-radius: var(--radius-md); }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 420px) {
  .products-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
}

/* ── Mobile nav drawer ── */
.mobile-nav {
