/* ── Cart state ── */
let cartCount = 0;
const cartBadge = document.getElementById('cart-badge');

function updateCartBadge() {
  cartBadge.textContent = cartCount;
  cartBadge.hidden = cartCount === 0;
  cartBadge.setAttribute('aria-label', `${cartCount} item${cartCount !== 1 ? 's' : ''} in cart`);
}

/* ── Toast notifications ── */
const toastContainer = document.getElementById('toast-container');

function showToast(message, type = 'success') {
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  const icon = type === 'success' ? '✓' : '✕';
  toast.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span> ${message}`;
  toastContainer.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('hiding');
    toast.addEventListener('animationend', () => toast.remove());
  }, 3200);
}

/* ── Add to cart ── */
document.querySelectorAll('.add-to-cart').forEach(btn => {
  btn.addEventListener('click', () => {
    const name = btn.dataset.name || 'Item';
    cartCount++;
    updateCartBadge();
    btn.classList.add('added');
    btn.textContent = 'Added ✓';
    btn.setAttribute('aria-label', `${name} added to cart`);
    setTimeout(() => {
      btn.classList.remove('added');
      btn.textContent = 'Add to Cart';
      btn.setAttribute('aria-label', `Add ${name} to cart`);
    }, 2000);
    showToast(`"${name}" added to cart!`);
  });
});

/* ── Deal add to cart ── */
document.querySelectorAll('.deal-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const name = btn.dataset.name || 'Deal item';
    cartCount++;
    updateCartBadge();
    showToast(`"${name}" added to cart!`);
  });
});

/* ── Wishlist toggle ── */
document.querySelectorAll('.product-wishlist').forEach(btn => {
  btn.addEventListener('click', () => {
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    btn.textContent = pressed ? '♡' : '♥';
    const name = btn.dataset.name || 'Item';
    showToast(
      pressed ? `"${name}" removed from wishlist` : `"${name}" saved to wishlist`,
      pressed ? 'error' : 'success'
    );
  });
});

/* ── Category chips ── */
document.querySelectorAll('.category-chip').forEach(chip => {
  chip.addEventListener('click', () => {
    document.querySelectorAll('.category-chip').forEach(c => {
      c.setAttribute('aria-pressed', 'false');
      c.classList.remove('active');
    });
    chip.setAttribute('aria-pressed', 'true');
    chip.classList.add('active');
  });
  chip.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      chip.click();
    }
  });
});

/* ── Countdown timer ── */
function updateCountdown() {
  const targets = document.querySelectorAll('[data-countdown]');
  targets.forEach(el => {
    const endTime = parseInt(el.dataset.countdown, 10);
    const now = Date.now();
    const diff = Math.max(0, endTime - now);
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const units = el.querySelectorAll('.countdown-num');
    if (units[0]) units[0].textContent = String(h).padStart(2, '0');
    if (units[1]) units[1].textContent = String(m).padStart(2, '0');
    if (units[2]) units[2].textContent = String(s).padStart(2, '0');
    el.setAttribute('aria-label', `${h} hours ${m} minutes ${s} seconds remaining`);
  });
}
updateCountdown();
setInterval(updateCountdown, 1000);

/* ── Set countdown end times ── */
document.querySelectorAll('[data-countdown-hours]').forEach(el => {
  const hours = parseFloat(el.dataset.countdownHours);
  el.dataset.countdown = String(Date.now() + hours * 3600000);
});
updateCountdown();

